-- APPLIED TO PRODUCTION 2026-11-15 (project nwrflbpbhyiqdptmlccm). Seeds the first 13 role packs and the founder's staff row.
-- Generated from code by validating each pack with parseRolePack; the database guard re-checks every invariant.
BEGIN;
-- Founder staff row: links the single active super admin; platform_admin is human-only (no agent pack), so the context waits as pending_pack.
WITH u AS (SELECT id, email FROM auth.users WHERE id = (SELECT id FROM public.super_admins WHERE is_active LIMIT 1)),
s AS (INSERT INTO public.platform_staff (id, email, full_name, department, status, invited_by, activated_at)
      SELECT id, email, 'Vibeora', 'Executive', 'active', id, now() FROM u
      ON CONFLICT (id) DO NOTHING RETURNING id)
SELECT u.id, 'platform_admin', u.id FROM u ON CONFLICT (staff_id, role_code) DO NOTHING;

SELECT public.cg_twin_reconcile();
COMMIT;
